
.index {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: clamp(6px, 1.2vw, 12px) 0;
  padding: clamp(14px, 2.4vw, 20px);
  border: 1px solid var(--panel-border, #46283a);
  border-radius: 14px;
  background: var(--panel-bg, rgba(14, 8, 12, 0.8));
  color: var(--text, #eee2e8);
}
.index__title { font-size: 1.1em; letter-spacing: 0.14em; color: var(--accent, #ff7db8); }
.index__modes { display: flex; flex-wrap: wrap; gap: 10px; }
.mode {
  flex: 1 1 200px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 11px 13px;
  border-radius: 10px;
}
.mode--on {
  border: 1.5px solid var(--accent, #ff7db8);
  background: rgba(255, 125, 184, 0.12);
  box-shadow: 0 0 12px rgba(255, 125, 184, 0.22);
}
.mode--soon {
  border: 1px dashed rgba(238, 226, 232, 0.28);
  background: rgba(20, 12, 16, 0.5);
  opacity: 0.75;
}
.mode__name { font-size: 1em; letter-spacing: 0.1em; }
.mode__tag {
  align-self: flex-start;
  padding: 0 6px;
  border: 1px solid rgba(255, 125, 184, 0.5);
  border-radius: 999px;
  font-size: 0.78em;
  letter-spacing: 0.06em;
}
.mode--soon .mode__tag { border-color: rgba(238, 226, 232, 0.3); }
.mode__desc { font-size: 0.85em; color: var(--muted, #a48f9c); }
.index__tiers { display: flex; flex-wrap: wrap; gap: 10px; }
.tier {
  appearance: none; flex: 1 1 140px; display: flex; flex-direction: column; gap: 6px;
  background: rgba(20, 12, 16, 0.7); color: var(--text, #eee2e8);
  border: 1px solid rgba(238, 226, 232, 0.2); border-radius: 10px; padding: 12px 14px;
  cursor: pointer; transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease;
}
.tier:hover { border-color: var(--accent, #ff7db8); box-shadow: 0 0 10px rgba(255, 125, 184, 0.4); }
.tier:active { transform: translateY(1px); }
.tier__name { font-size: 1em; letter-spacing: 0.1em; }
.tier__desc { font-size: 0.85em; color: var(--muted, #a48f9c); }
